<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Pending</title><style>body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;padding:40px}.card{max-width:560px;margin:auto;background:#fff;border-radius:18px;padding:30px;box-shadow:0 10px 30px #0001;text-align:center}.ref{font-family:monospace;background:#f1f5f9;padding:12px;border-radius:10px}button{margin-top:20px;padding:12px 18px;border:0;border-radius:10px;background:#0f766e;color:#fff;cursor:pointer}</style></head><body><div class="card"><h2>Payment in progress</h2><p>Complete the mobile-money prompt on your phone. The system will update your ISP account after confirmation.</p><p class="ref">{{ $tx->merchant_reference }}</p><p>Status: <strong id="status">{{ strtoupper($tx->status) }}</strong></p><button onclick="checkStatus()">Check payment status</button></div><script>async function checkStatus(){const r=await fetch(@json(route('payment.tanzania.status',$tx->merchant_reference)));const d=await r.json();document.getElementById('status').textContent=d.status.toUpperCase();if(d.status==='paid')location.href=@json(route('filament.portal.pages.pay-bill'));}setInterval(checkStatus,10000);</script></body></html>
